:root{--bg:#F6F4EE;--card:#fff;--ink:#14161A;--muted:#5B6470;--line:#DAD6CB;--soft:#ECE8DD;--pass:#17803D;--fail:#C9302C;--accent:#1B63D6;--accent-soft:#E6EEFC}
*{margin:0;padding:0;box-sizing:border-box}
html,body{width:1600px;height:900px;background:var(--bg);overflow:hidden}
body{font-family:Inter,sans-serif;color:var(--ink);position:relative}
.dots{position:absolute;inset:0;background-image:radial-gradient(#cfc9ba 1.2px,transparent 1.2px);background-size:28px 28px;opacity:.5;-webkit-mask-image:linear-gradient(180deg,#000,transparent 50%)}
.kicker{position:absolute;left:64px;top:52px;font-family:'JetBrains Mono',monospace;font-weight:500;font-size:17px;letter-spacing:2.6px;color:var(--muted);text-transform:uppercase}
.h1{position:absolute;left:64px;top:92px;width:1150px;font-weight:800;font-size:76px;letter-spacing:-2.6px;line-height:1}
.h1 em{font-style:normal;color:var(--accent)}
.sub{position:absolute;left:64px;top:262px;width:1100px;font-size:28px;line-height:1.4;color:var(--muted);font-weight:500}
.mark{position:absolute;right:64px;top:50px;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:32px;letter-spacing:-1px}
.mark i{display:inline-block;width:.5em;height:.8em;background:var(--accent);margin-left:5px;vertical-align:-3px}
.panel{position:absolute;background:var(--card);border:1.5px solid var(--line);border-radius:22px;box-shadow:0 22px 46px -28px rgba(20,22,26,.5)}
.chip{display:inline-block;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:16px;color:var(--accent);background:var(--accent-soft);border-radius:9px;padding:7px 13px}
.chip.r{color:var(--fail);background:#FBE9E8}.chip.g{color:var(--pass);background:#E3F4E8}.chip.n{color:var(--ink);background:var(--soft)}
.logo{width:48px;height:48px;border-radius:12px;display:block;flex:none}
.logo.w{background:#fff;border:1.5px solid var(--line);padding:7px}
.pill{display:inline-flex;align-items:center;gap:12px;background:var(--card);border:1.5px solid var(--line);border-radius:16px;padding:9px 20px 9px 11px;box-shadow:0 14px 28px -22px rgba(20,22,26,.5)}
.pill b{font-weight:800;font-size:26px;letter-spacing:-.6px}
.foot{position:absolute;left:64px;right:64px;bottom:34px;display:flex;justify-content:space-between;align-items:center;font-family:'JetBrains Mono',monospace;font-size:16px;color:var(--muted)}
.foot b{color:var(--ink)}
.node{background:var(--card);border:1.5px solid var(--line);border-radius:16px;padding:16px 18px;box-shadow:0 12px 26px -18px rgba(20,22,26,.4)}
.node b{display:block;font-weight:800;font-size:23px;letter-spacing:-.4px}
.node s{display:block;text-decoration:none;color:var(--muted);font-size:16px;margin-top:6px;line-height:1.35}
.node.bad{border-color:var(--fail);box-shadow:0 0 0 5px rgba(201,48,44,.08)}
.node.good{border-color:var(--pass);box-shadow:0 0 0 5px rgba(23,128,61,.08)}
.node.hot{border-color:var(--accent);background:var(--accent-soft)}

