/* Apple-style light system for the neatHack cards. Loaded last, so it overrides each card's own tokens.
   Register: brand. Strategy: restrained, tinted neutrals and one blue. Type: Geist (SF Pro stand-in), Geist Mono for code only. */
:root{--bg:#F5F5F7;--card:#FBFBFD;--ink:#1D1D1F;--muted:#6E6E73;--line:#D8D8DE;--soft:#EBEBF0;--pass:#1F8A3B;--fail:#D70015;--accent:#0066CC;--accent-soft:#E8F1FC;--shadow:0 1px 2px rgba(29,29,31,.05),0 14px 40px -14px rgba(29,29,31,.16)}
html,body{background:var(--bg)!important}
body{font-family:'Geist',-apple-system,BlinkMacSystemFont,'SF Pro Display','Helvetica Neue',sans-serif!important;color:var(--ink);-webkit-font-smoothing:antialiased}
.dots,.glow,.glow2,.grid,.wash{display:none!important}
/* eyebrow and headline */
.kicker{font-family:'Geist',sans-serif!important;text-transform:none!important;letter-spacing:-.01em!important;font-weight:600!important;font-size:22px!important;color:var(--accent)!important}
.h1,.tag{font-family:'Geist',sans-serif!important;font-weight:700!important;letter-spacing:-.04em!important}
.h1 em,.tag em{font-style:normal;color:var(--accent)!important}
.tag em{color:var(--pass)!important}
.sub{font-weight:400!important;color:var(--muted)!important;letter-spacing:-.01em}
/* surfaces */
.panel,.node,.card,.lane,.band,.term,.pill{background:var(--card)!important;border:1px solid rgba(29,29,31,.07)!important;border-radius:26px!important;box-shadow:var(--shadow)!important}
.node{border-radius:20px!important}
.pill{border-radius:999px!important}
.node.bad{border-color:rgba(215,0,21,.55)!important}.node.good{border-color:rgba(31,138,59,.55)!important}.node.hot{border-color:rgba(0,102,204,.5)!important;background:var(--accent-soft)!important}
.band{border-color:rgba(0,102,204,.45)!important}
.node b,.tname,.mark,.h1{font-family:'Geist',sans-serif}
.node b{font-weight:700!important;letter-spacing:-.02em!important}
.node s,.node .i{font-family:'Geist',sans-serif!important;color:var(--muted)!important}
.node .i{font-weight:600}
/* chips become quiet pills */
.chip,.role,.lab,.rl,.rl span{font-family:'Geist',sans-serif!important;text-transform:none!important;letter-spacing:-.005em!important;font-weight:600!important}
.chip,.role{border-radius:999px!important;padding:6px 14px!important;font-size:15px!important}
.role{font-size:14px!important;color:var(--accent)!important;background:var(--accent-soft)!important}
.role.k{color:var(--ink)!important;background:var(--soft)!important}
.chipcol .chip{font-family:'Geist Mono',monospace!important;font-weight:500!important;font-size:14px!important}
.chip.n{color:var(--ink)!important;background:var(--soft)!important}
/* wordmark, labels, footer */
.mark .w,.mark{font-family:'Geist Mono',monospace!important;font-weight:600!important}
.foot,.foot span,.cap,.capin{font-family:'Geist',sans-serif!important;font-size:15px!important;letter-spacing:-.005em!important}
.code{font-family:'Geist Mono',monospace!important;font-weight:500!important}
.tab{border-right:1px solid rgba(29,29,31,.07)!important}
.tab .n,.tname{font-weight:700!important;letter-spacing:-.03em!important}
.tab .r{font-family:'Geist',sans-serif!important;text-transform:none!important;letter-spacing:0!important;font-weight:600!important;font-size:16px!important;color:var(--accent)!important}
.res,.res b,.list,.list b{font-family:'Geist',sans-serif!important}
.pin{background:var(--pass)!important}.pin.fix{background:var(--accent)!important}
.lab{background:var(--bg)!important;border:1px solid rgba(0,102,204,.45)!important;border-radius:999px!important}
