/* 4:5 base for LinkedIn cards, 1080x1350. Loaded before apple.css. */
:root{--bg:#F5F5F7;--card:#FBFBFD;--ink:#1D1D1F;--muted:#6E6E73;--line:#D8D8DE;--soft:#EBEBF0;--pass:#1F8A3B;--fail:#D70015;--accent:#0066CC;--accent-soft:#E8F1FC}
*{margin:0;padding:0;box-sizing:border-box}
html,body{width:1080px;height:1350px;overflow:hidden}
body{position:relative}
.eyebrow{position:absolute;left:72px;top:84px;font-weight:600;font-size:30px;letter-spacing:-.01em;color:var(--accent)}
.mark{position:absolute;right:72px;top:80px;font-weight:600;font-size:34px;letter-spacing:-1px}
.mark i{display:inline-block;width:.5em;height:.8em;background:var(--accent);margin-left:5px;vertical-align:-3px}
.title{position:absolute;left:72px;top:150px;width:900px;font-weight:700;font-size:104px;letter-spacing:-.045em;line-height:.98}
.title em{font-style:normal;color:var(--accent)}
.lead{position:absolute;left:72px;width:900px;font-size:34px;line-height:1.35;color:var(--muted);letter-spacing:-.01em}
.stack{position:absolute;left:72px;right:72px;display:flex;flex-direction:column;gap:22px}
.row{background:var(--card);border:1px solid rgba(29,29,31,.07);border-radius:28px;box-shadow:0 1px 2px rgba(29,29,31,.05),0 14px 40px -14px rgba(29,29,31,.16);padding:30px 36px;display:flex;align-items:center;gap:28px}
.row .n{width:60px;height:60px;border-radius:50%;background:var(--soft);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:28px;flex:none}
.row b{display:block;font-weight:700;font-size:38px;letter-spacing:-.03em}
.row s{display:block;text-decoration:none;color:var(--muted);font-size:26px;margin-top:6px;line-height:1.3}
.row.bad{border-color:rgba(215,0,21,.5)}.row.bad .n{background:#FBE9EA;color:var(--fail)}
.row.good{border-color:rgba(31,138,59,.5)}.row.good .n{background:#E4F4E8;color:var(--pass)}
.row.hot{border-color:rgba(0,102,204,.5);background:var(--accent-soft)}.row.hot .n{background:#fff;color:var(--accent)}
.pill{display:inline-flex;align-items:center;gap:14px;background:var(--card);border:1px solid rgba(29,29,31,.07);border-radius:999px;padding:10px 26px 10px 12px;box-shadow:0 14px 28px -22px rgba(29,29,31,.5)}
.pill b{font-weight:700;font-size:30px;letter-spacing:-.03em}
.logo{width:48px;height:48px;border-radius:12px;display:block}
.logo.w{background:#fff;border:1.5px solid var(--line);padding:7px}
.foot{position:absolute;left:72px;right:72px;bottom:64px;display:flex;justify-content:space-between;font-size:24px;color:var(--muted)}
.foot b{color:var(--ink)}

